using System.IO;
using System.Windows;
using System.Windows.Media;
using System.Windows.Media.Imaging;

namespace GeMMeElec;

public static class EngineeringTests
{
    public static void Run(Action<string,Action> test,Action<bool,string> assert,Action<Action> reject,string dir)
    {
        test("Fiches fabricants : sources, documents intègres, affectation et bornage conservé",()=>{
            assert(ArticleFiches.All.Count==3&&ArticleFiches.Search("phoenix").Single().Reference=="3209510","Sélection sourcée");foreach(var f in ArticleFiches.All.Where(f=>f.Document.Length>0))assert(ArticleFiches.ReadDocument(f).Length>1000,"Document absent");var e=new Editor();var c=e.AddComponent("contactor",200,200);var ports=c.Definition.Ports.ToList();string before=ProjectStore.Serialize(e.Project);e.AssignArticleFiche(c.Id,"schneider-LC1D09BD");assert(c.Reference=="LC1D09BD"&&c.Definition.Ports.SequenceEqual(ports)&&ArticleFiches.For(c)?.Width==45,"Affectation modifiant le bornage");e.Undo();assert(ProjectStore.Serialize(e.Project)==before,"Article non annulable");var official=e.AddComponent("official-schneider-LC1D09BD",500,500);reject(()=>e.AssignArticleFiche(official.Id,"pilz-750104"));assert(ArticleFiches.Search("750104").Single().Height is null,"Dimension non vérifiée inventée");
        });
        test("Numérotation : familles, contacts associés, verrous et aperçu périmé",()=>{
            var e=new Editor();var coil=e.AddComponent("coil",200,200);var contact=e.AddComponent("contact_no",400,200);e.AssociateContact(contact.Id,coil.Id);var locked=e.AddComponent("coil",600,200);e.Change(()=>{locked.Tag="K99";locked.TagLocked=true;});var terminal=e.AddComponent("terminal",300,400);var wire=e.Connect(new(coil.Id,"A2"),new(terminal.Id,"1"),number:"PRESERVE",numberIndependent:true);var common=e.Connect(new(terminal.Id,"2"),new(contact.Id,"13"),number:"26");var plan=AutoNumbering.Preview(e.Project,new(){ComponentPattern="{prefix}{n:000}",WirePattern="{prefix}{folio}-{n:00}",Start=2});string before=ProjectStore.Serialize(e.Project);e.ApplyNumbering(plan);
            assert(coil.Tag=="K002"&&contact.Tag=="K002"&&locked.Tag=="K99"&&wire.Number=="PRESERVE"&&common.Number=="W1-02","Numérotation ou verrous perdus");e.Undo();assert(ProjectStore.Serialize(e.Project)==before,"Annulation partielle");e.Redo();reject(()=>e.ApplyNumbering(plan));reject(()=>AutoNumbering.Preview(e.Project,new(){ComponentPattern="{bad}"}));
        });
        test("Numérotation : conflits prévus, périmètre et sauvegarde des règles",()=>{
            var e=new Editor();var a=e.AddComponent("coil",200,200);e.Change(()=>{a.Tag="K1";a.TagLocked=true;});var b=e.AddComponent("coil",500,200);var plan=AutoNumbering.Preview(e.Project,new(){Scope="components",Start=1});assert(!plan.CanApply&&plan.Changes.Any(c=>c.Status=="Conflit"),"Conflit masqué");reject(()=>e.ApplyNumbering(plan));plan=AutoNumbering.Preview(e.Project,new(){Scope="components",Start=2});e.ApplyNumbering(plan);var path=Path.Combine(dir,"self-test-numbering.gemelec");e.Save(path);assert(ProjectStore.Load(path).NumberingRules.Start==2&&b.Tag=="K2","Règles non persistantes");
        });
        test("Bornier : ports, pontage, raccordements, plans et suppression annulable",()=>{
            var e=new Editor();var a=e.AddComponent("terminal",200,300);var b=e.AddComponent("terminal_pe",500,300);var src=e.AddComponent("coil",200,100);var dst=e.AddComponent("coil",500,550);e.Connect(new(src.Id,"A2"),new(a.Id,"1"),number:"24V");e.Connect(new(b.Id,"2"),new(dst.Id,"A1"),number:"PE");var strip=new TerminalStrip{Name="X10",Location="Armoire commande",Terminals=[new(){ComponentId=a.Id,Number="1"},new(){ComponentId=b.Id,Number="2",Level=2}],Bridges=[new(){FromComponent=a.Id,ToComponent=b.Id}]};e.PutTerminalStrip(strip);
            assert(CrossReferences.Trace(e.Project,new(src.Id,"A2")).Contains(new Endpoint(dst.Id,"A1")),"Pontage non raccordé");assert(TerminalStrips.Rows(e.Project,strip)[0].Internal.Contains(src.Tag),"Départ absent");var pages=e.GenerateTerminalPlan(strip.Id);assert(pages.Count>=2&&Drawing.Scene(e.Project,pages[0]).Any(i=>i.Text.Contains("X10")),"Plan non généré");Export.Pdf(e.Project,Path.Combine(dir,"self-test-terminal-plan.pdf"));var path=Path.Combine(dir,"self-test-terminal-plan.gemelec");e.Save(path);assert(ProjectStore.Load(path).TerminalStrips.Single().Bridges.Count==1,"Pontage perdu à la lecture");e.SelectSheet(e.Project.Sheets[0].Id);string before=ProjectStore.Serialize(e.Project);e.Delete([a.Id]);assert(e.Project.TerminalStrips[0].Terminals.Count==1&&e.Project.TerminalStrips[0].Bridges.Count==0,"Affectation orpheline");e.Undo();assert(ProjectStore.Serialize(e.Project)==before,"Suppression non annulable");
        });
        test("Bornier : niveaux explicites, pagination sans perte et rejet de bobine",()=>{
            var e=new Editor();var a=e.AddComponent("terminal",200,300);var coil=e.AddComponent("coil",500,300);var strip=new TerminalStrip{Name="X20",Terminals=[new(){ComponentId=a.Id,Number="1",Comment=string.Join(' ',Enumerable.Repeat("COMMENTAIRE",150))}]};e.PutTerminalStrip(strip);var pages=e.GenerateTerminalPlan(strip.Id);string full=string.Join(" ",pages.SelectMany(s=>Drawing.Scene(e.Project,s)).Where(i=>i.Kind=="text").Select(i=>i.Text));assert(full.Split("COMMENTAIRE").Length-1==150&&pages.Count>1,"Commentaire tronqué");reject(()=>e.PutTerminalStrip(new(){Terminals=[new(){ComponentId=coil.Id,InternalPort="A1",ExternalPort="A2"}]}));reject(()=>e.PutTerminalStrip(new(){Terminals=[new(){ComponentId=a.Id},new(){ComponentId=a.Id,Number="2"}]}));
        });
        test("Armoire : dimensions explicites, drag, plans et connexions conservées",()=>{
            var e=new Editor();var a=e.AddComponent("coil",200,200);var b=e.AddComponent("coil",500,500);var wire=e.Connect(new(a.Id,"A2"),new(b.Id,"A1"));var cabinet=new CabinetLayout{Name="A1",Width=600,Height=800,Items=[new(){ComponentId=a.Id,Width=45,Height=80,X=50,Y=50},new(){Kind="rail",Name="R1",Width=500,Height=35,X=30,Y=100},new(){Kind="duct",Name="G1",Width=40,Height=500,X=530,Y=50}]};e.PutCabinet(cabinet);var draft=DocumentModel.Copy(cabinet);var preview=new CabinetPreview(e.Project,draft);assert(preview.Begin(new(60,60)),"Objet non sélectionnable");preview.Move(new(120,90));preview.End();assert(draft.Items[0].X==110&&draft.Items[0].Y==80&&e.Project.Cabinets[0].Items[0].X==50,"Aperçu altérant le modèle");e.PutCabinet(draft);assert(wire.From==new Endpoint(a.Id,"A2")&&a.X==200,"Schéma déplacé avec l’implantation");var sheet=e.GenerateCabinetPlan(cabinet.Id);Export.Pdf(e.Project,Path.Combine(dir,"self-test-cabinet-plan.pdf"));var path=Path.Combine(dir,"self-test-cabinet-plan.gemelec");e.Save(path);assert(ProjectStore.Load(path).Cabinets[0].Items[0].X==110&&sheet.CabinetPlanId==cabinet.Id,"Implantation perdue");var visual=new DrawingVisual();using(var dc=visual.RenderOpen()){dc.DrawRectangle(Brushes.White,null,new(0,0,1400,990));Drawing.Render(dc,Drawing.Scene(e.Project,sheet));}var png=new PngBitmapEncoder();var bitmap=new RenderTargetBitmap(1400,990,96,96,PixelFormats.Pbgra32);bitmap.Render(visual);png.Frames.Add(BitmapFrame.Create(bitmap));using var file=File.Create(Path.Combine(dir,"apercu-implantation.png"));png.Save(file);
        });
        test("Armoire : limites, chevauchements, suppression et rollback",()=>{
            var e=new Editor();var a=e.AddComponent("coil",200,200);var cabinet=new CabinetLayout{Items=[new(){ComponentId=a.Id,Width=40,Height=80,X=20,Y=20},new(){ComponentId=a.Id,Width=40,Height=80,X=30,Y=30}]};e.PutCabinet(cabinet);assert(Cabinets.Findings(e.Project,cabinet).Count>=3,"Doublons et chevauchements absents");string before=ProjectStore.Serialize(e.Project);reject(()=>e.PutCabinet(new(){Items=[new(){ComponentId=a.Id,X=590,Width=100,Height=80}]}));assert(ProjectStore.Serialize(e.Project)==before,"Rollback d’implantation");e.Delete([a.Id]);assert(e.Project.Cabinets[0].Items.Count==0,"Implantation orpheline");e.Undo();assert(ProjectStore.Serialize(e.Project)==before,"Undo suppression implantation");
        });
        test("Gestionnaires métier : aperçu de numérotation, borniers, armoire et fiches",()=>{
            string? old=Environment.GetEnvironmentVariable("GEMMEELEC_TEST_SESSION");Environment.SetEnvironmentVariable("GEMMEELEC_TEST_SESSION","1");var window=new MainWindow();int probes=0;try{var a=window.Editor.AddComponent("terminal",200,200);var b=window.Editor.AddComponent("terminal",500,500);window.Canvas.Select(a.Id);window.Canvas.Selected.Add(b.Id);window.DocumentTestProbe=dialog=>{probes++;var content=(FrameworkElement)dialog.Content;content.Measure(new(1200,750));content.Arrange(new(0,0,1200,750));content.UpdateLayout();assert(content.ActualWidth>500,"Gestionnaire non disposé");};foreach(string command in new[]{"numbering","terminalStrips","cabinet","articleFiches"})window.WorkspaceCommandForTest(command).Execute(null,window);assert(probes==4,"Gestionnaire non ouvert");}finally{window.DocumentTestProbe=null;window.DisposeTestBridge();Environment.SetEnvironmentVariable("GEMMEELEC_TEST_SESSION",old);}
        });
    }
}
